class Solution:
    def lowestCommonAncestor(self, root: TreeNode, p: Any, q: Any) -> Any:
        p_val = p.val if isinstance(p, TreeNode) else p
        q_val = q.val if isinstance(q, TreeNode) else q
        curr = root
        while curr:
            if p_val > curr.val and q_val > curr.val:
                curr = curr.right
            elif p_val < curr.val and q_val < curr.val:
                curr = curr.left
            else:
                return curr.val if curr else None

